function canCompleteCircuit(gas, cost) {
  let tank = 0, start = 0;
  for (let i = 0; i < gas.length; i++) {
    tank += gas[i] - cost[i];
    if (tank < 0) return -1; // BUG: kills feasible circuits
  }
  return start;
}
